from lib import *
S = SS('g21')
steps = [
    step("不同写法的 defer 成本(每个函数 //go:noinline,7 轮取中位数):直接调用 inc() 1.97 ns/op,defer inc() 1.98 ns/op——一个 defer 几乎没有额外成本;Lock + 直接 Unlock 7.64 ns/op,Lock + defer Unlock 11.79 ns/op(多约 4 ns);8 个 defer 15.27 ns/op,9 个 defer 58.47 ns/op;循环里的 defer(只循环 1 次)17.95 ns/op;4 个 defer × 4 个 return 的函数 29.63 ns/op;defer 里带 recover 的函数正常返回 3.32 ns/op,panic 后被 recover 接住 144.53 ns/op。所有这些函数的 AllocsPerRun 都是 0。", t=tl(S(1)), done=lidx(S(1), 'noDefer', 'oneDefer', 'lockDirect', 'lockDefer', 'eightDefers'), mark=lidx(S(1), 'nineDefers', 'loopDefer', 'manyReturns', 'withPanic'), b=bars([['直接调用 inc()', 1.97, '1.97'], ['defer inc()', 1.98, '1.98'], ['8 个 defer', 15.27, '15.27'], ['9 个 defer', 58.47, '58.47'], ['4 defer × 4 return', 29.63, '29.63'], ['panic + recover', 144.53, '144.53']], 144.53, done=[0, 1, 2], mark=[3, 4, 5]), kv=KV([['1 个 defer', '1.98 ns,与直接调用相同'], ['8 个 vs 9 个 defer', '15.27 ns vs 58.47 ns'], ['Lock+defer Unlock', '11.79 ns vs 直接 Unlock 7.64 ns'], ['panic 后 recover', '144.53 ns'], ['分配', '全部 0 次']], ['8 个 vs 9 个 defer'])),
    step("编译器的分类(-gcflags=-d=defer=1):oneDefer、lockDefer、eightDefers(8 个)、withRecover、withPanic 都是 open-coded defer;nineDefers(9 个)与 manyReturns(4 个 defer × 4 个 return)是 stack-allocated defer;loopDefer(循环里)是 heap-allocated defer。汇编里:open-coded 的函数只出现 runtime.deferreturn;nineDefers 与 manyReturns 额外调用 runtime.deferprocStack;loopDefer 调用 runtime.deferproc。", t=tl(S(2)), done=lidx(S(2), 'oneDefer     open-coded', 'eightDefers  open-coded'), mark=lidx(S(2), 'nineDefers   stack-allocated', 'loopDefer    heap-allocated', 'manyReturns  stack-allocated', 'deferprocStack', 'runtime.deferproc,'), kv=KV([['≤ 8 个 defer 且不在循环里', 'open-coded defer'], ['9 个 defer / 4 defer × 4 return', 'stack-allocated(deferprocStack)'], ['循环里的 defer', 'heap-allocated(deferproc)']], ['≤ 8 个 defer 且不在循环里'])),
    step("关掉 open-coded defer(-gcflags=-d=noopendefer=1),同一份代码:oneDefer 从 1.99 变成 13.23 ns/op;lockDefer 从 12.30 变成 19.90;eightDefers 从 15.63 变成 54.05;loopDefer 不变(18.11 与 18.17,因为它本来就不是 open-coded);noDefer 不变。", t=tl(S(3)), done=lidx(S(3), '默认:'), mark=lidx(S(3), '-gcflags=-d=noopendefer=1'), b=bars([['oneDefer 默认', 1.99, '1.99'], ['oneDefer 关闭 open-coded', 13.23, '13.23'], ['eightDefers 默认', 15.63, '15.63'], ['eightDefers 关闭 open-coded', 54.05, '54.05']], 54.05, done=[0, 2], mark=[1, 3]), kv=KV([['oneDefer', '1.99 → 13.23 ns'], ['eightDefers', '15.63 → 54.05 ns'], ['loopDefer', '18.11 / 18.17 ns,不变'], ['结论', 'open-coded defer 把每个 defer 的额外成本从约 11 ns 降到接近 0']], ['结论'])),
    step("源码里 open-coded 的限制:walk/stmt.go:defer 超过 maxOpenDefers(8 个,因为用一个字节记录哪些 defer 还活着),或需要 deferprocat,或 defer 出现在循环里(n.Esc() != ir.EscNever)就禁用;ssagen/ssa.go:s.curfn.NumReturns*s.curfn.NumDefers > 15 也禁用(每个出口都要生成 defer 调用)。这与实测一致:9 个 defer、4×4 = 16 个出口乘 defer、循环里的 defer 都不是 open-coded。", t=tl(S(4)), done=lidx(S(4), 'NumDefers > maxOpenDefers', 'more than'), mark=lidx(S(4), 'n.Esc() != ir.EscNever', 'NumReturns*s.curfn.NumDefers > 15'), kv=KV([['> 8 个 defer', '禁用:一个字节记录活着的 defer'], ['defer 在循环里', '禁用(heap-allocated)'], ['返回点数 × defer 数 > 15', '禁用:每个出口都要生成调用']], ['> 8 个 defer'])),
]
A = mkartg('g21', 21, 'Go,defer,open-coded defer,性能,真实验证,动画演示',
    '在 Go 1.27.1 里实测 defer 的成本:一个 defer 与直接调用一样快(1.98 ns vs 1.97 ns),8 个以内且不在循环里的 defer 是 open-coded,第 9 个、返回点数乘 defer 数超过 15、或在循环里就退化成 deferprocStack / deferproc(8 个 15.27 ns,9 个 58.47 ns);关闭 open-coded 后 1 个 defer 变成 13.23 ns;panic 后被 recover 接住约 144.53 ns;并对照编译器源码里的限制。',
    '“defer 很慢”是一个过时的说法。Go 1.14 引入了 open-coded defer,把大多数 defer 编译成函数出口处的直接调用。这篇测出它到底快多少,什么时候会退化,并用编译器自己的诊断与源码里的限制条件对照。',
    [('1.98 ns', '一个 defer inc() 的耗时,与直接调用 inc() 的 1.97 ns 相同'), ('8 → 9', '8 个 defer 15.27 ns,9 个 defer 58.47 ns:超过 8 个就不再是 open-coded'), ('13.23 ns', '关闭 open-coded 后一个 defer 的耗时(默认 1.99 ns)')],
    [('一个 defer 几乎免费', '<p>open-coded defer 把 <code>defer f()</code> 在函数的每个出口直接展开成对 <code>f()</code> 的调用(再加一个栈上的位图记录哪些 defer 要执行),不需要运行时在堆或栈上登记。所以 <code>oneDefer</code> 与直接调用没有可测的差别。加锁加 defer 解锁比直接解锁多约 4 ns,这是被 defer 的 <code>Unlock</code> 无法内联造成的,不是 defer 本身的成本(这一点是我的解释,没有进一步验证)。</p>'),
     ('三种 defer', '<p><code>-d=defer=1</code> 把每个 defer 分成 open-coded、stack-allocated、heap-allocated 三类。第 9 个 defer 起或出口太多就变成 stack-allocated(调用 <code>deferprocStack</code>,在栈上建记录),在循环里的 defer 才是 heap-allocated(调用 <code>deferproc</code>,需要运行时管理记录)。AllocsPerRun 在三种情形下都是 0——说明运行时有记录的复用,我没有去读它的实现。</p>'),
     ('关掉看看', '<p>用 <code>-d=noopendefer=1</code> 关掉这项优化,同一份代码里每个 defer 多花约 11 ns,而循环里的 defer 不变,证明它本来就走另一条路径。9 个 defer 与 8 个 defer 之间那个 3.8 倍的跳变(15.27 → 58.47 ns)就是跨过 open-coded 限制的代价。</p>'),
     ('限制来自哪里', '<p>编译器里这几条限制写得很清楚:defer 数用一个字节的位图记录,所以最多 8 个;循环里的 defer 次数运行时才知道,不能展开;出口数乘 defer 数超过 15 时展开的代码太多就放弃。实用的结论是:函数里少放 defer、不要在热循环里 defer;但没必要为了“省 defer”而去掉一个 <code>defer mu.Unlock()</code>。</p>')],
    steps,
    [ENV_G + '。每个函数 //go:noinline,基准测试 7 轮取中位数;分类来自 go build -gcflags=-d=defer=1,汇编来自 -S;读过的源码:cmd/compile/internal/walk/stmt.go、ssagen/ssa.go(限制条件)',
     '没有验证:amd64 与其它版本的数字、defer 记录复用的运行时实现(deferpool 一类)、recover 路径为什么需要约 145 ns、带闭包捕获变量的 defer 的额外开销、loop 里 defer 的 N 次迭代成本随 N 的变化'],
    'defer 的成本')
